import numpy as np
from scipy.optimize import least_squares
from scipy.spatial.transform import Rotation
p=np.loadtxt('xtbopt.xyz',skiprows=2,usecols=(1,2,3));
inds=[0,2]; targets=[[552,333],[558,475]]
for k,coords in enumerate([[(430,170),(386,279),(406,393),(266,267),(240,152),(343,90)],[(659,246),(739,337),(706,455),(845,290),(840,172),(724,144)],[(436,519),(497,628),(593,647),(407,718),(304,657),(328,537)]]):
 for a,xy in zip([1,2,3,4,9,10],coords):
  inds.append(3+21*k+a-1); targets.append(xy)
q=np.array(targets,dtype=float); q[:,1]*=-1; q-=q.mean(axis=0)
for parity in [1,-1]:
 pp=p.copy(); pp[:,0]*=parity; sel=pp[inds]; sel-=sel.mean(axis=0)
 def err(x):return (np.exp(x[3])*(sel@Rotation.from_rotvec(x[:3]).as_matrix().T)[:,:2]-q).ravel()
 best=None
 for i in range(80):
  x=np.r_[np.random.normal(size=3)*2,np.log(50)]
  r=least_squares(err,x)
  if best is None or np.sum(r.fun*r.fun)<best[0]: best=(np.sum(r.fun*r.fun),r)
 e,r=best; rot=Rotation.from_rotvec(r.x[:3]).as_matrix(); proj=pp@rot.T
 print(parity,'error',e,'scale',np.exp(r.x[3]),'BH z',proj[1,2]-proj[0,2], 'In S z', [proj[k,2]-proj[2,2] for k in [5,26,47]])
